/// <summary>
/// An environment that receives copies, identified by its Power Platform or LCS environment ID
/// like <c>SysEnvironmentModeMap</c>.
/// </summary>
public class BDREnvironment extends common
{
}

Method.Source:
    public static BDREnvironment find(BDREnvironmentId _environmentId, boolean _forUpdate = false)
    {
        BDREnvironment environment;

        if (_environmentId)
        {
            environment.selectForUpdate(_forUpdate);

            select firstonly environment
                where environment.EnvironmentId == _environmentId;
        }

        return environment;
    }

    public static BDREnvironment findBySysEnvironmentId(SysEnvironmentid _sysEnvironmentId)
    {
        BDREnvironment environment;

        if (_sysEnvironmentId)
        {
            select firstonly environment
                where environment.SysEnvironmentId == _sysEnvironmentId;
        }

        return environment;
    }

public static boolean exist(BDREnvironmentId _environmentId)
{
    return _environmentId && (select firstonly RecId from BDREnvironment
        where BDREnvironment.EnvironmentId == _environmentId).RecId != 0;
}

/// <summary>
/// Shows whether this environment is the instance the user is working in.
/// </summary>
public display NoYes isCurrent()
{
    return BDREnvironmentResolver::isCurrent(this.SysEnvironmentId) ? NoYes::Yes : NoYes::No;
}

    public void modifiedField(FieldId _fieldId)
    {
        super(_fieldId);

        if (_fieldId == fieldNum(BDREnvironment, SysEnvironmentId))
        {
            this.SysEnvironmentId = strLwr(strLRTrim(this.SysEnvironmentId));
        }
    }

    /// <summary>
    /// Adds every enabled task type that is not yet part of the environment, inactive, with its default sequence.
    /// </summary>
    public void addAllTaskTypes()
    {
        BDRTaskType taskType;
        BDREnvironmentTask environmentTask;

        if (!this.EnvironmentId)
        {
            return;
        }

        ttsbegin;

        while select taskType
            where taskType.IsEnabled == NoYes::Yes
            notexists join environmentTask
                where environmentTask.EnvironmentId == this.EnvironmentId
                    && environmentTask.TaskTypeName == taskType.Name
        {
            BDREnvironmentTask newTask;

            newTask.EnvironmentId = this.EnvironmentId;
            newTask.TaskTypeName = taskType.Name;
            newTask.Sequence = taskType.DefaultSequence;
            newTask.IsActive = NoYes::No;
            newTask.insert();
        }

        ttscommit;
    }
